UPDATE t_recon_exception
SET status = #{status}, active_slot = #{activeSlot}, closed_time = #{closedTime}, version = version + 1, update_time = #{now}
WHERE id = #{record.id} AND version = #{record.version} AND status = #{record.status}

UPDATE t_recon_exception
SET status = #{status}, active_slot = #{activeSlot}, closed_time = #{closedTime}, version = version + 1, update_time = #{now}
WHERE id IN #{r.id}
  AND (id, version, status) IN (#{r.id}, #{r.version}, #{r.status})
